def caps_for(platform, app_path, device_name, platform_version):
    p = platform.lower()
    if p == 'android':
        name, engine, exts = 'Android', 'UiAutomator2', ('.apk', '.aab')
    elif p == 'ios':
        name, engine, exts = 'iOS', 'XCUITest', ('.app', '.ipa')
    else:
        raise ValueError(f'unknown platform {platform}')
    if not app_path.lower().endswith(exts):
        raise ValueError(f'{app_path} is not a {name} app')
    return {
        'platformName': name,
        'appium:automationName': engine,
        'appium:app': app_path,
        'appium:deviceName': device_name,
        'appium:platformVersion': platform_version,
    }

